SELECT is(
  (SELECT string_agg(src || '.' || col || '->' || dst, ' ' ORDER BY src || '.' || col) FROM (
    SELECT c.conrelid::regclass::text AS src, a.attname::text AS col, c.confrelid::regclass::text AS dst
