-- One seeded row of each parent table per tenant: what the ref checks point at.
CREATE TEMP TABLE iso_parent (tbl text, tenant uuid, id uuid) ON COMMIT DROP;
INSERT INTO iso_parent SELECT 'public.agreements', tenant_id, (array_agg(id ORDER BY id))[1] FROM public.agreements WHERE tenant_id IS NOT NULL GROUP BY tenant_id;
INSERT INTO iso_parent SELECT 'public.community_spaces', tenant_id, (array_agg(id ORDER BY id))[1] FROM public.community_spaces WHERE tenant_id IS NOT NULL GROUP BY tenant_id;
