SELECT set_config('stellr.tenant_id', '', true);
SELECT is((SELECT v FROM iso_obs WHERE ctx = 'b' AND tbl = 'public.agreements' AND chk = 'see_other'), '0', 'canary context: sees 0 Stellr rows of public.agreements');
SELECT is((SELECT v FROM iso_obs WHERE ctx = 'b' AND tbl = 'public.agreements' AND chk = 'see_all'), (SELECT n FROM iso_expect WHERE tbl = 'public.agreements' AND tenant = 'c0ffee00-0000-4000-8000-0000000000b2')::text, 'canary context: sees exactly its own rows of public.agreements');
SELECT is((SELECT v FROM iso_obs WHERE ctx = 'b' AND tbl = 'public.agreements' AND chk = 'update_other'), '0', 'canary context: UPDATE of Stellr rows of public.agreements touches 0');
SELECT is((SELECT v FROM iso_obs WHERE ctx = 'b' AND tbl = 'public.agreements' AND chk = 'delete_other'), '0', 'canary context: DELETE of Stellr rows of public.agreements touches 0');
SELECT is((SELECT v FROM iso_obs WHERE ctx = 'b' AND tbl = 'public.agreements' AND chk = 'insert_other'), 'ERR:42501', 'canary context: INSERT of a Stellr row into public.agreements is refused by RLS');
SELECT is((SELECT v FROM iso_obs WHERE ctx = 'b' AND tbl = 'public.agreements' AND chk = 'insert_own'), '1', 'canary context: INSERT of its own row into public.agreements works');
SELECT is((SELECT v FROM iso_obs WHERE ctx = 'b' AND tbl = 'public.agreements' AND chk = 'event_unknown'), 'ERR:42501', 'canary context: a public.agreements row under an event its tenant does not have is refused, even with its own tenant_id');
SELECT is((SELECT v FROM iso_obs WHERE ctx = 'b' AND tbl = 'public.agreements' AND chk = 'ref_missing:participant_id'), 'ERR:42501', 'canary context: public.agreements.participant_id naming an id that does not exist is refused by RLS (no FK error to probe with)');
